PROGRAM
using System.Text.Json;
using Microsoft.AspNetCore.Diagnostics.HealthChecks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Diagnostics.HealthChecks;

var builder = WebApplication.CreateBuilder(args);

builder.WebHost.UseUrls("http://localhost:5099");

var databasePath = Path.Combine(builder.Environment.ContentRootPath, "recipes.db");
builder.Services.AddDbContext<RecipeDbContext>(options =>
    options.UseSqlite($"Data Source={databasePath}"));
builder.Services.AddHealthChecks()
    .AddCheck<RecipeDatabaseHealthCheck>("sqlite", tags: ["ready"]);

var app = builder.Build();

await using (var scope = app.Services.CreateAsyncScope())
{
    var db = scope.ServiceProvider.GetRequiredService<RecipeDbContext>();
    await db.Database.EnsureCreatedAsync();
}

var recipes = app.MapGroup("/api/recipes");

recipes.MapGet("/", async (
    string? title,
    string? ingredient,
    string? instructions,
    RecipeDbContext db,
    CancellationToken cancellationToken) =>
{
    var items = await db.Recipes
        .AsNoTracking()
        .OrderBy(recipe => recipe.Title)
        .ThenBy(recipe => recipe.Id)
        .Select(recipe => recipe.ToResponse())
        .ToListAsync(cancellationToken);

    var matches = items.Where(recipe =>
        (title is null || ContainsIgnoreCase(recipe.Title, title)) &&
        (ingredient is null || recipe.Ingredients.Any(value => ContainsIgnoreCase(value, ingredient))) &&
        (instructions is null || ContainsIgnoreCase(recipe.Instructions, instructions)));

    return Results.Ok(matches);
});

recipes.MapPost("/", async (RecipeRequest request, RecipeDbContext db, CancellationToken cancellationToken) =>
{
    var validationProblem = Validate(request);
    if (validationProblem is not null)
    {
        return validationProblem;
    }

    var id = string.IsNullOrWhiteSpace(request.Id)
        ? Guid.NewGuid().ToString("N")
        : request.Id.Trim();

    if (await db.Recipes.AnyAsync(recipe => recipe.Id == id, cancellationToken))
    {
        return Results.Conflict(new { error = $"A recipe with id '{id}' already exists." });
    }

    var recipe = RecipeEntity.FromRequest(id, request);
    db.Recipes.Add(recipe);
    await db.SaveChangesAsync(cancellationToken);

    return Results.CreatedAtRoute("GetRecipe", new { id = recipe.Id }, recipe.ToResponse());
});

recipes.MapGet("/{id}", async (string id, RecipeDbContext db, CancellationToken cancellationToken) =>
{
    var recipe = await db.Recipes.AsNoTracking()
        .SingleOrDefaultAsync(recipe => recipe.Id == id, cancellationToken);

    return recipe is null ? Results.NotFound() : Results.Ok(recipe.ToResponse());
}).WithName("GetRecipe");

recipes.MapPut("/{id}", async (string id, RecipeRequest request, RecipeDbContext db, CancellationToken cancellationToken) =>
{
    var validationProblem = Validate(request);
    if (validationProblem is not null)
    {
        return validationProblem;
    }

    var recipe = await db.Recipes.SingleOrDefaultAsync(recipe => recipe.Id == id, cancellationToken);
    if (recipe is null)
    {
        return Results.NotFound();
    }

    recipe.Title = request.Title!.Trim();
    recipe.IngredientsJson = JsonSerializer.Serialize(request.Ingredients!);
    recipe.Instructions = request.Instructions!.Trim();
    await db.SaveChangesAsync(cancellationToken);

    return Results.Ok(recipe.ToResponse());
});

recipes.MapDelete("/{id}", async (string id, RecipeDbContext db, CancellationToken cancellationToken) =>
{
    var deleted = await db.Recipes.Where(recipe => recipe.Id == id).ExecuteDeleteAsync(cancellationToken);
    return deleted == 0 ? Results.NotFound() : Results.NoContent();
});

app.MapHealthChecks("/health", HealthCheckOptions());
app.MapHealthChecks("/health/ready", HealthCheckOptions());

app.Run();

static bool ContainsIgnoreCase(string source, string value) =>
    source.Contains(value, StringComparison.OrdinalIgnoreCase);

static IResult? Validate(RecipeRequest request)
{
    var errors = new Dictionary<string, string[]>();

    if (string.IsNullOrWhiteSpace(request.Title))
    {
        errors["title"] = ["Title is required."];
    }

    if (request.Ingredients is null)
    {
        errors["ingredients"] = ["Ingredients are required."];
    }
    else if (request.Ingredients.Any(string.IsNullOrWhiteSpace))
    {
        errors["ingredients"] = ["Ingredients cannot contain blank values."];
    }

    if (string.IsNullOrWhiteSpace(request.Instructions))
    {
        errors["instructions"] = ["Instructions are required."];
    }

    return errors.Count == 0 ? null : Results.ValidationProblem(errors);
}

static HealthCheckOptions HealthCheckOptions() => new()
{
    Predicate = registration => registration.Tags.Contains("ready"),
    ResponseWriter = async (context, report) =>
    {
        context.Response.ContentType = "application/json";
        await context.Response.WriteAsJsonAsync(new
        {
            status = report.Status == HealthStatus.Healthy ? "ready" : "not_ready"
        });
    }
};

