using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Diagnostics.HealthChecks;

public sealed class RecipeDbContext(DbContextOptions<RecipeDbContext> options) : DbContext(options)
{
    public DbSet<RecipeEntity> Recipes => Set<RecipeEntity>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<RecipeEntity>(entity =>
        {
            entity.ToTable("Recipes");
            entity.HasKey(recipe => recipe.Id);
            entity.Property(recipe => recipe.Id).IsRequired();
            entity.Property(recipe => recipe.Title).IsRequired();
            entity.Property(recipe => recipe.IngredientsJson).IsRequired();
            entity.Property(recipe => recipe.Instructions).IsRequired();
        });
    }
}

public sealed class RecipeEntity
{
    public required string Id { get; init; }
    public required string Title { get; set; }
    public required string IngredientsJson { get; set; }
    public required string Instructions { get; set; }

    public static RecipeEntity FromRequest(string id, RecipeRequest request) => new()
    {
        Id = id,
        Title = request.Title!.Trim(),
        IngredientsJson = JsonSerializer.Serialize(request.Ingredients!),
        Instructions = request.Instructions!.Trim()
    };

    public RecipeResponse ToResponse() => new(
        Id,
        Title,
        JsonSerializer.Deserialize<List<string>>(IngredientsJson) ?? [],
        Instructions);
}

public sealed class RecipeDatabaseHealthCheck(RecipeDbContext db) : IHealthCheck
{
    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context,
        CancellationToken cancellationToken = default) =>
        await db.Database.CanConnectAsync(cancellationToken)
            ? HealthCheckResult.Healthy("SQLite database is ready.")
            : HealthCheckResult.Unhealthy("SQLite database is not available.");
}

